 const metric=(icon,value,label)=>`<article class="recruit-v2-metric">${cardIcon(icon)}<div><strong>${E(String(value??0))}</strong><span>${E(t(label))}</span></div></article>`;
 const actualScore=x=>x.score==null?null:Number(x.score);
 const resultVisual=x=>{const value=actualScore(x),max=Math.max(1,Number(x.maxScore)||100),pass=Number(x.passScore)||Math.ceil(max/2);if(value===null||!Number.isFinite(value))return '';const percentage=Math.max(0,Math.min(100,Math.round(100*value/max))),passed=value>=pass;return `<section class="recruit-v2-result"><div class="recruit-v2-donut ${passed?'passed':'failed'}" role="img" aria-label="${E(t('Your score'))}: ${value} / ${max}" style="--progress:${percentage}%"><div><strong>${percentage}%</strong><span>${E(t('Your score'))}</span></div></div><div class="recruit-v2-result-copy">${pill(x.status==='under-review'?'Assessment pending review':passed?'Passed':'Failed')}<h3>${E(t('Assessment completed'))}</h3><strong>${E(value)} / ${E(max)}</strong><p>${E(t('Passing score'))}: ${E(pass)} / ${E(max)}</p></div></section>`;};

 // Recruitment interview CTA: uses only reviewed, passing assessments and current application state.
 const assessmentPassMark=exam=>Number.isFinite(Number(exam?.passScore))&&Number(exam.passScore)>0?Number(exam.passScore):Math.ceil(Number(exam?.maxScore||100)/2);
 const approvedPass=exam=>!!exam&&['reviewed','passed'].includes(exam.status)&&exam.score!=null&&Number.isFinite(Number(exam.score))&&Number(exam.score)>=assessmentPassMark(exam);
 const awaitingReview=exam=>!!exam&&exam.status==='under-review';
 const reservedInterview=applicationId=>(relatedInterviews.get(applicationId)||[]).find(r=>P.reserves(r));
 const latestRelatedExam=applicationId=>(relatedExams.get(applicationId)||[]).slice().sort((a,b)=>Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0))[0]||null;
 const canScheduleForApp=app=>app?.decision==='pending'&&(!latestRelatedExam(app.id)||approvedPass(latestRelatedExam(app.id)));
 // Make the next authorized step visible from both the Applications and Assessments lists.
 // A numeric grade is provisional until reviewed; it must never unlock scheduling by itself.
 const candidateNextAction=app=>{
   if(role!=='Organization'||!app||app.decision!=='pending')return '';
   const active=reservedInterview(app.id);
   if(active)return B('View Interview','view-interview',active.id);
   const exam=latestRelatedExam(app.id);
   if(awaitingReview(exam))return B('Review exam','review-exam',exam.id).replace('class="btn btn-outline-primary"','class="btn btn-primary recruit-v3-primary"');
   if(approvedPass(exam))return B('Schedule Interview','schedule-from-exam',exam.id).replace('class="btn btn-outline-primary"','class="btn btn-primary recruit-v3-primary"');
   return '';
 };
 const examResultCTA=exam=>{
   if(role!=='Organization'||!approvedPass(exam))return '';
   const app=relatedApps.get(exam.applicationId),active=reservedInterview(exam.applicationId);
   if(!app||app.decision!=='pending')return '';
   if(latestRelatedExam(exam.applicationId)?.id!==exam.id)return '';
   const score=Number(exam.score),max=Math.max(1,Number(exam.maxScore)||100),pass=Number(exam.passScore)||Math.ceil(max/2);
   return `<section class="recruit-v3-pass-cta" aria-label="${E(t('Ready for interview'))}"><div class="recruit-v3-pass-heading"><span class="recruit-v3-pass-icon"><i class="bi bi-patch-check-fill" aria-hidden="true"></i></span><div class="recruit-v3-pass-title"><span class="recruit-v3-eyebrow">${E(t('Assessment Passed'))}</span><h3>${E(t(active?'Interview already scheduled':'Ready for interview'))}</h3><p>${E(t(active?'The interview has already been scheduled for this applicant.':'The candidate passed the assessment and is eligible for an interview.'))}</p></div><span class="recruit-v3-pass-mark">${E(Math.round(100*score/max))}%<small>${E(score)} / ${E(max)}</small></span></div><div class="recruit-v3-pass-bottom"><span class="recruit-v3-pass-min"><i class="bi bi-bullseye"></i> ${E(t('Passing score'))}: ${E(pass)} / ${E(max)}</span><div class="recruit-v3-cta-actions">${B('View Exam Result','exam-result',exam.id).replace('class="btn btn-outline-primary"','class="btn btn-outline-primary recruit-v3-secondary"')}${active?B('View Interview','view-interview',active.id).replace('class="btn btn-outline-primary"','class="btn btn-primary recruit-v3-primary"'):B('Schedule Interview','schedule-from-exam',exam.id).replace('class="btn btn-outline-primary"','class="btn btn-primary recruit-v3-primary"')}</div></div></section>`;
 };
 const B=(label,action,id,extra='')=>`<button class="btn btn-outline-primary" type="button" data-action="${action}" data-id="${E(id||'')}" ${extra}>${E(t(label))}</button>`;
 const label=(name,key,type='text',value='',required=false,wide=false)=>`<label class="${wide?'wide':''}">${E(t(name))}<input name="${key}" type="${type}" value="${E(value??'')}" ${required?'required':''}></label>`;
 const area=(name,key,value='',required=false)=>`<label class="wide">${E(t(name))}<textarea name="${key}" ${required?'required':''}>${E(value??'')}</textarea></label>`;
 const select=(name,key,choices,value)=>`<label>${E(t(name))}<select name="${key}">${choices.map(([id,title])=>`<option value="${E(id)}" ${value===id?'selected':''}>${E(t(title))}</option>`).join('')}</select></label>`;
 const date=x=>new Date(x).toLocaleString(document.documentElement.lang==='ar'?'ar-JO':'en-GB',{timeZone:'Asia/Amman'});
 const profileHTML=p=>{const names={firstName:'First name',lastName:'Last name',emailAddress:'Email',phoneNumber:'Phone',city:'City',educationLevel:'Education',university:'University',major:'Major',graduationYear:'Graduation year',yearsExperience:'Experience',skills:'Skills',professionalSummary:'Professional summary',linkedinUrl:'LinkedIn',portfolioUrl:'Portfolio'};const values=Object.fromEntries(Object.entries(names).filter(([k])=>p[k]).map(([k,n])=>[n,p[k]]));if(p.cvFileName||p.cvDocument?.name)values.CV=(p.cvFileName||p.cvDocument.name)+' · '+t(p.cvDocument?.id&&p.cvDocument?.uploaded===true?'Uploaded CV reference':'Preview only');return dl(values);};
 const notice=(msg,error=false)=>{const n=document.getElementById('recruitmentStatus');if(n){n.textContent=msg;n.classList.toggle('recruitment-danger',error);}};
 const dl=p=>'<dl>'+Object.entries(p).map(([k,v])=>`<dt>${E(t(k))}</dt><dd data-user-content>${E(typeof v==='object'?JSON.stringify(v,null,2):String(v??''))}</dd>`).join('')+'</dl>';
 function modal(title,html,onSubmit){if(dialog)dialog.close();dialog=document.createElement('dialog');dialog.className='recruitment-dialog';dialog.setAttribute('translate','no');dialog.setAttribute('aria-labelledby','recruitmentDialogTitle');dialog.innerHTML=`<header><h2 id="recruitmentDialogTitle" class="h4">${E(t(title))}</h2>${B('Close','close')}</header><div class="recruitment-detail">${html}</div><p id="recruitmentDialogError" role="alert" class="recruitment-danger"></p>`;document.body.append(dialog);const previous=document.activeElement,node=dialog;dialog.addEventListener('close',()=>{node.remove();if(dialog===node)dialog=null;if(previous?.isConnected)previous.focus();},{once:true});dialog.querySelector('[data-action=close]').addEventListener('click',()=>dialog.close());if(onSubmit)dialog.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.busy)return;form.dataset.busy='1';const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await onSubmit(new FormData(form),form);if(dialog)dialog.close();await load();notice(t('Action completed'));}catch(err){document.getElementById('recruitmentDialogError').textContent=t(err.message);}finally{if(form.isConnected){delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}}});dialog.showModal();dialog.querySelector('input,textarea,select,button')?.focus();return dialog;}
 const confirm=(title,run,reason=false)=>modal(title,`<form class="recruitment-form"><p class="wide">${E(t('Confirm this action?'))}</p>${reason?area('Reason / message','reason','',true):''}<div class="wide">${B('Confirm','submit',null,'type="submit"').replace('type="button"','')} </div></form>`,fd=>run(String(fd.get('reason')||'')));
 async function userApplicationForVacancy(vacancyId){if(role!=='User')return null;try{return (await S.list('applications',{current:false})).find(a=>a.vacancyId===vacancyId)||null;}catch{return null;}}
 async function organizationSubscriptionReady(){if(role!=='Organization')return true;try{const list=await WusoolServices.list('subscriptions'),now=Date.now();const active=(list.items||[]).some(x=>String(x.status||'').toLowerCase()==='active'&&(!x.renewalDate||Date.parse(x.renewalDate)>=now)&&(!x.endDate||Date.parse(x.endDate)>=now));if(active)return true;}catch{}root.innerHTML=`<div class="recruitment-panel recruitment-locked"><div class="recruitment-kicker">WUSOOL / ${E(t('Recruitment'))}</div><h1>${E(t('Recruitment is locked until renewal'))}</h1><p>${E(t('Please renew your organization subscription to use recruitment.'))}</p><a class="btn btn-primary" href="./subscription-management.html">${E(t('Renew subscription'))}</a></div>`;return false;}
 async function load(){const token=++loadId;root.setAttribute('aria-busy','true');try{if(!(await organizationSubscriptionReady()))return;records=view==='overview'?[]:await S.list(view,{current:!archive});if(view==='vacancies'&&role==='User'){try{applicationByVacancy=new Map((await S.list('applications',{current:false})).map(a=>[a.vacancyId,a]));}catch(_){applicationByVacancy=new Map();}}else applicationByVacancy=new Map();if(role==='Organization'&&(view==='exams'||view==='applications')){
  const [apps,interviews,exams]=await Promise.all([
    view==='applications'?Promise.resolve(records):S.list('applications',{current:false}),
    S.list('interviews',{current:false}),
    view==='exams'?Promise.resolve(records):S.list('exams',{current:false})
  ]);
  relatedApps=new Map(apps.map(a=>[a.id,a]));relatedInterviews=new Map();relatedExams=new Map();
  for(const interview of interviews){const list=relatedInterviews.get(interview.applicationId)||[];list.push(interview);relatedInterviews.set(interview.applicationId,list);}
  for(const exam of exams){const list=relatedExams.get(exam.applicationId)||[];list.push(exam);relatedExams.set(exam.applicationId,list);}
 }else{relatedApps=new Map();relatedInterviews=new Map();relatedExams=new Map();}
 const stats=isPublic?{}:await S.stats();if(token!==loadId)return;render(stats);if(dialog?.dataset.recordId){const updated=records.find(x=>x.id===dialog.dataset.recordId);if(updated&&updated.revision!==Number(dialog.dataset.revision)){if(role==='User'&&view==='exams'&&updated.status==='in-progress'&&dialog.querySelector('#examTimer'))dialog.dataset.revision=updated.revision;else await details(updated);}}}catch(err){if(token===loadId){root.innerHTML=`<div class="recruitment-panel"><h1>${E(t('Recruitment'))}</h1><p role="alert">${E(err.message)}</p><a href="../../visitor/html/home.html">Wusool</a></div>`;}}finally{if(token===loadId)root.setAttribute('aria-busy','false');}}
 function render(stats){
  const titles={overview:'Overview',vacancies:role==='User'?'Explore jobs':'Vacancies',applications:role==='User'?'My applications':'Applications center',exams:role==='User'?'My assessments':'Assessments center',interviews:role==='User'?'My interviews':'Interviews center',offers:role==='User'?'My offers':'Offers center'};
  const intro=role==='Organization'?'Manage vacancies, assessments, interviews and offers in one place.':role==='User'?'Discover opportunities, complete assessments, and track every application.':role==='Admin'?'Review applications and recruitment activity.':'Explore opportunities open to applicants.';
  const statsHtml=view==='overview'?`<section aria-labelledby="recruitOverviewTitle" class="recruit-v2-section"><div class="recruit-v2-section-heading"><div><div class="recruit-v2-eyebrow">WUSOOL ANALYTICS</div><h2 id="recruitOverviewTitle">${E(t('Everything at a glance'))}</h2></div></div><div class="recruitment-stats">${Object.entries({published:['briefcase','Published vacancies'],pending:['hourglass-split','Awaiting organization decision'],upcoming:['calendar-check','Upcoming interviews'],confirmations:['clock-history','Pending confirmations'],offers:['envelope-paper','Offers awaiting response'],starts:['check2-circle','Confirmed employment starts']}).map(([k,[icon,n]])=>metric(icon,stats[k],n)).join('')}</div><div class="recruit-v2-guide"><div><div class="recruit-v2-eyebrow">RECRUITMENT FLOW</div><h3>${E(t(role==='Admin'?'Recruitment process overview':'Your hiring journey'))}</h3><p>${E(t(role==='Admin'?'Monitor application, assessment, interview and decision stages.':'Complete your hiring milestones'))}</p></div><div class="recruit-v2-flow">${[['file-earmark-check','Application submitted'],['journal-text','Assessment'],['calendar-check','Interview'],['patch-check','Final decision']].map(([icon,label],i)=>`<div class="recruit-v2-flow-step">${cardIcon(icon)}<strong>${E(t(label))}</strong><small>${String(i+1).padStart(2,'0')}</small></div>`).join('')}</div></div></section>`:'';
  const toolsHtml=view!=='overview'?`<div class="recruitment-tools recruit-v2-tools"><label><span class="recruit-v2-field-label">${E(t('Search'))}</span><div class="recruit-v2-search"><i class="bi bi-search" aria-hidden="true"></i><input class="form-control" id="recruitmentSearch" value="${E(search)}" type="search" placeholder="${E(t('Search positions and candidates'))}"></div></label><label><span class="recruit-v2-field-label">${E(t('Status'))}</span><select class="form-select" id="recruitmentFilter"><option value="">${E(t('All'))}</option>${[...new Set(records.map(x=>x.status||x.decision).filter(Boolean))].map(s=>`<option value="${E(s)}" ${s===status?'selected':''}>${E(t(s))}</option>`).join('')}</select></label>${role==='Organization'&&view==='vacancies'?B('Create vacancy','create'):''}${role==='User'&&view==='applications'?B(archive?'Current':'Archive','archive'):''}</div><div class="recruit-v2-list" id="recruitmentRows"></div>${view==='applications'?`<div class="recruitment-note">${E(t('Rejected applications remain current for 48 hours then move to archive'))}</div>`:''}`:'';
  root.innerHTML=`<section class="recruit-v2-hero"><div class="recruit-v2-hero-copy"><span class="recruit-v2-hero-kicker"><i class="bi bi-stars" aria-hidden="true"></i> WUSOOL / ${E(t('Career center'))}</span><h1>${E(t(titles[view]))}</h1><p>${E(t(intro))}</p><div class="recruit-v2-hero-small"><span><i class="bi bi-shield-check" aria-hidden="true"></i> ${E(t('Recruitment'))}</span><span><i class="bi bi-diagram-3" aria-hidden="true"></i> ${E(t('Application pipeline'))}</span></div></div><div class="recruit-v2-hero-art" aria-hidden="true"><div class="recruit-v2-orbit orbit-outer"></div><div class="recruit-v2-orbit orbit-inner"></div><div class="recruit-v2-art-center"><i class="bi bi-briefcase-fill"></i></div><span class="recruit-v2-float-icon first"><i class="bi bi-patch-check-fill"></i></span><span class="recruit-v2-float-icon second"><i class="bi bi-file-earmark-check-fill"></i></span><span class="recruit-v2-float-icon third"><i class="bi bi-mortarboard-fill"></i></span></div></section><nav class="recruitment-nav" aria-label="${E(t('Recruitment'))}">${(isPublic?['vacancies']:views).map(v=>`<a href="?view=${v}" data-view="${v}" ${view===v?'aria-current="page"':''}><i class="bi bi-${icons[v]}" aria-hidden="true"></i><span>${E(t(v[0].toUpperCase()+v.slice(1)))}</span></a>`).join('')}</nav><p id="recruitmentStatus" class="recruitment-status" role="status" aria-live="polite"></p>${statsHtml}${toolsHtml}${WusoolServices.mode==='local'?`<p class="recruit-v2-dev-note">${E(t('Local development records; no server operation is implied'))}</p>`:''}`;
  if(view!=='overview'){const sortLabel=document.createElement('label');sortLabel.textContent=t('Sort by');const sortSelect=document.createElement('select');sortSelect.className='form-select';const options=[['default','Default'],['newest','Newest first'],['oldest','Oldest first'],['name','Name'],['status','Status']];if(['exams','interviews'].includes(view))options.push(['upcoming','Upcoming first']);for(const [value,title] of options)sortSelect.add(new Option(t(title),value));sortSelect.value=options.some(o=>o[0]===sortOrder)?sortOrder:'default';sortLabel.append(sortSelect);root.querySelector('.recruitment-tools').append(sortLabel);sortSelect.onchange=()=>{sortOrder=sortSelect.value;page=1;renderRows();};renderRows();root.querySelector('#recruitmentSearch').addEventListener('input',e=>{search=e.target.value;page=1;renderRows();});root.querySelector('#recruitmentFilter').addEventListener('change',e=>{status=e.target.value;page=1;renderRows();});}
}

  function renderRows(){
 let filtered=records.filter(x=>(!status||(x.status||x.decision)===status)&&[x.title,x.organizationName,x.snapshot?.firstName,x.snapshot?.lastName,x.interviewerName,x.candidateMessage].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))).filter(x=>!(archive&&role==='User'&&view==='applications')||!P.current(x));
 const order=sortOrder==='default'?(['exams','interviews'].includes(view)?'upcoming':'newest'):sortOrder;const rules=order==='upcoming'?[{field:'startAt',type:'date'}]:order==='name'?[{field:'title'}]:order==='status'?[{field:'status'},{field:'decision'}]:[{field:'createdAt',type:'date',direction:order==='newest'?'desc':'asc'}];filtered=WusoolSort.stable(filtered,rules,document.documentElement.lang);const count=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,count);
 const item=x=>{const state=x.status||x.decision||'pending',subtitle=x.organizationName||[x.snapshot?.firstName,x.snapshot?.lastName].filter(Boolean).join(' ')||x.interviewerName||'',stamp=x.startAt?date(x.startAt):x.closingDate||date(x.createdAt),icon=icons[view]||'briefcase';
  const description=view==='vacancies'?`<div class="recruit-v2-meta"><span><i class="bi bi-geo-alt"></i> ${E(x.branchSnapshot?.city||x.branchSnapshot?.name||t('Location'))}</span><span><i class="bi bi-people"></i> ${E(x.positions??'-')} ${E(t('Positions'))}</span><span><i class="bi bi-clock"></i> ${E(stamp)}</span></div>`:view==='exams'?`<div class="recruit-v2-meta"><span><i class="bi bi-stopwatch"></i> ${E(x.durationMinutes??'-')} ${E(t('Minutes'))}</span><span><i class="bi bi-list-check"></i> ${E(x.questionCount||x.questions?.length||0)} ${E(t('Questions'))}</span><span><i class="bi bi-bullseye"></i> ${E(x.passScore??'-')} / ${E(x.maxScore||100)} ${E(t('Passing mark'))}</span></div>`:view==='interviews'?`<div class="recruit-v2-meta"><span><i class="bi bi-calendar-event"></i> ${E(date(x.startAt))}</span><span><i class="bi bi-camera-video"></i> ${E(t(x.mode||''))}</span></div>`:`<div class="recruit-v2-meta"><span><i class="bi bi-calendar3"></i> ${E(stamp)}</span>${x.employmentStatus?`<span>${E(t(x.employmentStatus))}</span>`:''}</div>`;
  const briefProgress=view==='applications'?`<div class="recruit-v2-card-progress"><div class="recruit-v2-card-progress-line"><span>${E(t('Application submitted'))}</span><span>${E(t(x.decision==='rejected'?'Rejected':x.decision==='accepted'?'Accepted':x.examStatus==='reviewed'?'Assessment':x.examStatus==='under-review'?'Exam awaiting review':'Pending'))}</span></div><div class="recruit-v2-track-mini"><span class="filled"></span><span class="${x.examStatus?'filled':''}"></span><span class="${x.decision==='accepted'||x.decision==='proceed-to-offer'?'filled':''}"></span><span class="${['rejected','accepted'].includes(x.decision)?'filled':''}"></span></div></div>`:'';
  const score=view==='exams'&&x.score!=null?`<span class="recruit-v2-score-mini">${E(x.score)} / ${E(x.maxScore||100)}</span>`:'';
  return `<article class="recruit-v2-item"><div class="recruit-v2-item-header">${cardIcon(icon)}<div class="recruit-v2-item-heading"><h3>${E(x.title||t(view[0].toUpperCase()+view.slice(1)))}</h3><p>${E(subtitle||t('Recruitment'))}</p></div><div class="recruit-v2-state">${pill(state)}${score}</div></div>${description}${briefProgress}<div class="recruit-v2-item-footer"><span class="recruit-v2-footer-sub"><i class="bi bi-arrow-up-right-circle" aria-hidden="true"></i> ${E(t('Current stage'))}: ${E(t(state))}</span><div class="recruit-v2-footer-actions">${B('Open details','details',x.id)}${view==='vacancies'&&role==='User'&&x.status==='published'?(applicationByVacancy.has(x.id)?B('Track application','track-existing-app',applicationByVacancy.get(x.id).id):B('Apply','apply',x.id)):''}${view==='applications'?B('View application journey','track-app',x.id):''}${role==='Organization'&&view==='applications'?candidateNextAction(x):''}${role==='Organization'&&view==='exams'&&latestRelatedExam(x.applicationId)?.id===x.id?candidateNextAction(relatedApps.get(x.applicationId)):''}</div></div></article>`;
 };
 const target=document.getElementById('recruitmentRows');if(!target)return;
 target.innerHTML=filtered.length?`<div class="recruit-v2-list-title"><div><span class="recruit-v2-eyebrow">${E(t('Recruitment'))}</span><h2>${E(t(view[0].toUpperCase()+view.slice(1)))}</h2></div><span class="recruit-v2-count">${filtered.length}</span></div><div class="recruit-v2-item-grid">${filtered.slice((page-1)*8,page*8).map(item).join('')}</div><div class="recruitment-pagination">${B('Previous','previous',null,page===1?'disabled':'')}<span>${page} / ${count} · ${filtered.length}</span>${B('Next','next',null,page===count?'disabled':'')}</div>`:`<div class="recruitment-empty"><span class="recruit-v2-icon large"><i class="bi bi-search"></i></span><h2>${E(t(search||status?'No matching results':'No records yet'))}</h2><p>${E(t(search||status?'Clear filters to see more records.':'Complete your hiring milestones'))}</p></div>`;
}

  async function vacancyForm(v={}){const branches=(await WusoolServices.getBranches()).filter(b=>b.organizationId===account.id&&!b.isDeleted);modal(v.id?'Edit':'Create vacancy',`<form class="recruitment-form">${label('Title','title','text',v.title,true,true)}${area('Description','description',v.description,true)}${area('Responsibilities','responsibilities',v.responsibilities)}${area('Qualifications','qualifications',v.qualifications,true)}${area('Skills','skills',v.skills)}${label('Positions','positions','number',v.positions||1,true)}${select('Employment type','employmentType',['full-time','part-time','contract','internship'].map(x=>[x,x]),v.employmentType)}${select('Work arrangement','workArrangement',['onsite','remote','hybrid'].map(x=>[x,x]),v.workArrangement)}${select('Branch','branchId',[['','Optional branch'],...branches.map(b=>[b.id,b.name||b.branchName])],v.branchId)}${label('Closing date','closingDate','date',v.closingDate,true)}${area('Accommodations','accommodations',v.accommodations)}<fieldset class="wide"><legend class="h6">${E(t('Custom questions'))}</legend><div id="recruitmentQuestions"></div>${B('Add question','add-question')}</fieldset><div class="wide"><button type="submit" class="btn btn-primary">${E(t('Save'))}</button></div></form>`,async(fd,form)=>{const input=Object.fromEntries(fd);input.questions=[...form.querySelectorAll('.recruitment-question')].map(row=>({label:row.querySelector('input[type=text]').value,required:row.querySelector('[type=checkbox]').checked}));await S.saveVacancy({...input,id:v.id,revision:v.revision});});const add=q=>{const row=document.createElement('div');row.className='recruitment-question recruitment-tools';row.innerHTML=`<label>${E(t('Question label'))}<input type="text" value="${E(q?.label||'')}" required></label><label><input type="checkbox" ${q?.required?'checked':''}> ${E(t('Required'))}</label><button type="button" class="btn btn-outline-danger">${E(t('Remove'))}</button>`;row.querySelector('button').onclick=()=>row.remove();dialog.querySelector('#recruitmentQuestions').append(row);};(v.questions||[]).forEach(add);dialog.querySelector('[data-action=add-question]').onclick=()=>add();}
