  // Client-side answer recovery is advisory: authoritative exam timing and grading belong on the service/backend.
 const assessmentSaves=new Map();
 function currentExam(exam){return records.find(x=>x.id===exam.id)||exam;}
 function queueAssessmentSave(exam,answers){
   const task=(assessmentSaves.get(exam.id)||Promise.resolve()).then(async()=>{
     const current=currentExam(exam),updated=await S.saveExamAnswers(exam.id,Math.max(current.revision,exam.revision),{answers});
     Object.assign(current,updated);Object.assign(exam,updated);
     if(dialog?.dataset.recordId===exam.id)dialog.dataset.revision=updated.revision;
   }).catch(error=>{const message=document.getElementById('recruitmentDialogError');if(message&&dialog?.dataset.recordId===exam.id)message.textContent=t(error.code==='EXAM_EXPIRED'?error.message:'Unable to save exam answers. Please retry before time ends.');});
   assessmentSaves.set(exam.id,task);return task;
 }
 function updateEmploymentEntry(){for(const button of document.querySelectorAll('[data-action="confirm-start"]')){const app=records.find(x=>x.id===button.dataset.id);button.disabled=!app||app.decision!=='accepted'||app.employmentStatus==='start-confirmed'||!app.employmentStartAt||Date.now()<Date.parse(app.employmentStartAt);}}
 function assessmentDraftKey(exam){return 'wusool:recruitment:assessment:'+String(exam.userId||'')+':'+String(exam.id);}
 function setupAssessmentDraft(exam){
   const form=dialog?.querySelector('.recruitment-exam-list');if(!form)return;
   const key=assessmentDraftKey(exam);let saved=exam.savedAnswers||{};
   try{const raw=JSON.parse(sessionStorage.getItem(key)||'{}');if(raw&&raw.examId===exam.id&&raw.startedAt===exam.startedAt&&raw.answers&&typeof raw.answers==='object')saved={...raw.answers,...saved};}catch(_){/* Storage can be unavailable. */}
   for(const field of form.querySelectorAll('input[type=radio]')){if(!form.querySelector('input[name="'+CSS.escape(field.name)+'"]:checked')&&saved[field.name.slice(2)]===field.value)field.checked=true;}
   const progress=()=>{const count=form.querySelectorAll('input[type=radio]:checked').length,total=exam.questions.length;const label=form.querySelector('#assessmentProgress'),fill=form.querySelector('#assessmentProgressFill');if(label)label.textContent=count+' / '+total;if(fill)fill.style.width=(total?count/total*100:0)+'%';};
   form.addEventListener('change',()=>{const answers=Object.fromEntries([...form.querySelectorAll('input[type=radio]:checked')].map(i=>[i.name.slice(2),i.value]));try{sessionStorage.setItem(key,JSON.stringify({examId:exam.id,startedAt:exam.startedAt,answers,savedAt:Date.now()}));}catch(_){/* Best-effort recovery only. */}queueAssessmentSave(exam,answers);progress();});progress();if(!exam.savedAnswers&&Object.keys(saved).length&&Date.now()<Math.min(Date.parse(exam.deadlineAt),Date.parse(exam.startedAt)+Number(exam.durationMinutes)*60000))queueAssessmentSave(exam,saved);
 }
