	 function applicationActions(app,track){if(role!=='Organization')return '';const exams=track.exams||[],interviews=track.interviews||[],offers=track.offers||[],latestExam=latestRecord(exams),reserved=interviews.find(x=>P.reserves(x)),ended=interviews.some(x=>x.status==='ended'),activeOffer=offers.find(x=>!['declined','withdrawn'].includes(x.status));let actions=B('Track application','track-app',app.id);if(app.decision==='accepted'&&app.employmentStatus!=='start-confirmed')actions+=B('Schedule work start','schedule-work-start',app.id);if(app.decision==='accepted'&&app.employmentStatus!=='start-confirmed'&&app.employmentStartAt)actions+=B('Confirm employment start','confirm-start',app.id,Date.now()<Date.parse(app.employmentStartAt)?'disabled':'');if(['rejected','accepted'].includes(app.decision))return `<div class="recruitment-actions">${actions}</div>`;if(app.decision==='proceed-to-offer')return `<div class="recruitment-actions">${actions}${activeOffer?'':B('Issue offer','offer',app.id)}</div>`;if(activeOffer)return `<div class="recruitment-actions">${actions}</div>`;if(reserved)return `<div class="recruitment-actions">${actions}${B('View Interview','view-interview',reserved.id)}${B('Reject','reject-app',app.id)}</div>`;if(latestExam&&latestExam.status==='under-review')return `<div class="recruitment-actions">${actions}${B('Review exam','review-exam',latestExam.id)}${B('Reject','reject-app',app.id)}</div>`;if(latestExam&&['sent','in-progress'].includes(latestExam.status))return `<div class="recruitment-actions">${actions}${B('Reject','reject-app',app.id)}</div>`;if(latestExam&&latestExam.status==='failed')return `<div class="recruitment-actions">${actions}${B('Create exam','create-exam',app.id)}${B('Reject','reject-app',app.id)}</div>`;if(approvedPass(latestExam))return `<div class="recruitment-actions">${actions}${B('Schedule Interview','schedule',app.id).replace('class="btn btn-outline-primary"','class="btn btn-primary recruit-v3-primary"')}${B('Reject','reject-app',app.id)}</div>`;if(ended)return `<div class="recruitment-actions">${actions}</div>`;return `<div class="recruitment-actions">${actions}${B('Create exam','create-exam',app.id)}${B('Schedule round','schedule',app.id)}${B('Reject','reject-app',app.id)}</div>`;}
